import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase, initSchema, withImmediate, nowIso, type JobRow } from './db.ts';

const STEP_MS = 100;
const IDLE_MS = 200;
const HEARTBEAT_MS = 1000;
const MAX_ATTEMPTS = 3;
const RETRY_DELAY_MS = 500;

const db = openDatabase();
initSchema(db);
let stopping = false;

function writeHeartbeat(): void {
  db.prepare(
    'INSERT INTO worker_heartbeat (id, last_seen) VALUES (1, ?) ON CONFLICT(id) DO UPDATE SET last_seen = excluded.last_seen',
  ).run(Date.now());
}

/**
 * Re-queues jobs left `running` by a worker that died. The interrupted attempt is re-run under the
 * same number, so the decrement keeps `attempts` and the failAttempts behaviour unchanged.
 */
function recoverInterruptedJobs(): number {
  const result = db
    .prepare(
      `UPDATE jobs SET status = 'queued', attempts = MAX(attempts - 1, 0), progress_completed = 0,
              available_at = ?, updated_at = ? WHERE status = 'running'`,
    )
    .run(Date.now(), nowIso());
  return Number(result.changes);
}

/** Claims the oldest runnable queued job, moving it to `running` for a new attempt. */
function claimNextJob(): JobRow | undefined {
  return withImmediate(db, () => {
    const row = db
      .prepare(`SELECT * FROM jobs WHERE status = 'queued' AND available_at <= ? ORDER BY seq ASC LIMIT 1`)
      .get(Date.now()) as unknown as JobRow | undefined;
    if (!row) return undefined;
    db.prepare(
      `UPDATE jobs SET status = 'running', attempts = attempts + 1, progress_completed = 0, updated_at = ? WHERE id = ?`,
    ).run(nowIso(), row.id);
    return db.prepare('SELECT * FROM jobs WHERE id = ?').get(row.id) as unknown as JobRow;
  });
}

/** Puts a job back in the queue without counting the attempt, used when the worker is stopping. */
function abortAttempt(id: string): void {
  db.prepare(
    `UPDATE jobs SET status = 'queued', attempts = MAX(attempts - 1, 0), progress_completed = 0,
            updated_at = ? WHERE id = ? AND status = 'running'`,
  ).run(nowIso(), id);
}

/** Runs one attempt of a claimed job. Returns early, without a final write, if the worker is stopping. */
async function runAttempt(job: JobRow): Promise<void> {
  const attempt = job.attempts;

  if (attempt <= job.fail_attempts) {
    await sleep(STEP_MS);
    if (stopping) return abortAttempt(job.id);
    if (attempt < MAX_ATTEMPTS) {
      db.prepare(
        `UPDATE jobs SET status = 'queued', progress_completed = 0, available_at = ?, updated_at = ?
         WHERE id = ? AND status = 'running'`,
      ).run(Date.now() + RETRY_DELAY_MS, nowIso(), job.id);
    } else {
      db.prepare(
        `UPDATE jobs SET status = 'failed', error = 'transient failure', result_output = NULL, progress_completed = 0,
                updated_at = ? WHERE id = ? AND status = 'running'`,
      ).run(nowIso(), job.id);
    }
    return;
  }

  const updateProgress = db.prepare(
    `UPDATE jobs SET progress_completed = ?, updated_at = ? WHERE id = ? AND status = 'running'`,
  );
  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) return abortAttempt(job.id);
    updateProgress.run(step, nowIso(), job.id);
  }

  db.prepare(
    `UPDATE jobs SET status = 'completed', result_output = ?, progress_completed = ?, error = NULL, updated_at = ?
     WHERE id = ? AND status = 'running'`,
  ).run(job.input.toUpperCase(), job.steps, nowIso(), job.id);
}

function onSignal(): void {
  stopping = true;
}
for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, onSignal);
}

recoverInterruptedJobs();
writeHeartbeat();
const heartbeat = setInterval(() => {
  try {
    writeHeartbeat();
  } catch (e) {
    console.error('heartbeat failed:', e);
  }
}, HEARTBEAT_MS);

console.log('worker started');
while (!stopping) {
  let job: JobRow | undefined;
  try {
    job = claimNextJob();
  } catch (e) {
    console.error('claim failed:', e);
  }
  if (!job) {
    await sleep(IDLE_MS);
    continue;
  }
  try {
    await runAttempt(job);
  } catch (e) {
    console.error(`attempt for job ${job.id} failed:`, e);
    try {
      abortAttempt(job.id);
    } catch {
      // the job stays running and is recovered on the next worker start
    }
  }
}

clearInterval(heartbeat);
try {
  db.prepare('DELETE FROM worker_heartbeat').run();
} catch {
  // the heartbeat simply goes stale
}
db.close();
process.exit(0);

