import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { openDatabase, initSchema, withImmediate, rowToJob, nowIso, type JobRow } from './db.ts';

const MAX_BODY_BYTES = 1_000_000;
const MAX_INPUT_LENGTH = 1000;
const HEARTBEAT_FRESH_MS = 3000;
const ID_KEY_PATTERN = /^[A-Za-z0-9_-]{1,128}$/;
const ALLOWED_KEYS = new Set(['input', 'steps', 'failAttempts']);
const JOB_ID_PATH = /^\/api\/jobs\/([^/]+)$/;

interface FieldError {
  field: string;
  message: string;
}

const db = openDatabase();
initSchema(db);
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

function sendJson(res: ServerResponse, status: number, body: unknown): void {
  const text = JSON.stringify(body);
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', 'content-length': Buffer.byteLength(text) });
  res.end(text);
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  const error: { code: string; message: string; fields?: FieldError[] } = { code, message };
  if (fields) error.fields = fields;
  sendJson(res, status, { error });
}

function sendInvalid(res: ServerResponse, fields: FieldError[]): void {
  sendError(res, 400, 'invalid_request', 'The request is invalid.', fields);
}

function readBody(req: IncomingMessage): Promise<{ tooLarge: boolean; text: string }> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) tooLarge = true;
      else chunks.push(chunk);
    });
    req.on('end', () => resolve({ tooLarge, text: Buffer.concat(chunks).toString('utf8') }));
    req.on('error', reject);
  });
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function isIntegerIn(value: unknown, min: number, max: number): value is number {
  return typeof value === 'number' && Number.isInteger(value) && value >= min && value <= max;
}

/** Validates a POST /api/jobs body. Collects every problem into `errors`. */
function validateCreateBody(text: string, tooLarge: boolean, errors: FieldError[]):
  | { input: string; steps: number; failAttempts: number }
  | undefined {
  if (tooLarge) {
    errors.push({ field: 'body', message: 'Request body is too large.' });
    return undefined;
  }

  let parsed: unknown;
  try {
    parsed = JSON.parse(text);
  } catch {
    errors.push({ field: 'body', message: 'Request body must be valid JSON.' });
    return undefined;
  }
  if (!isPlainObject(parsed)) {
    errors.push({ field: 'body', message: 'Request body must be a JSON object.' });
    return undefined;
  }

  for (const key of Object.keys(parsed)) {
    if (!ALLOWED_KEYS.has(key)) errors.push({ field: key, message: 'Unknown field.' });
  }

  const { input, steps, failAttempts } = parsed;
  const inputOk = typeof input === 'string' && input.length >= 1 && input.length <= MAX_INPUT_LENGTH && input.trim() !== '';
  if (!inputOk) {
    errors.push({ field: 'input', message: `Required string of 1 to ${MAX_INPUT_LENGTH} characters, not only whitespace.` });
  }
  const stepsValue = steps === undefined ? 5 : steps;
  if (!isIntegerIn(stepsValue, 1, 20)) errors.push({ field: 'steps', message: 'Must be an integer from 1 to 20.' });
  const failValue = failAttempts === undefined ? 0 : failAttempts;
  if (!isIntegerIn(failValue, 0, 5)) errors.push({ field: 'failAttempts', message: 'Must be an integer from 0 to 5.' });

  if (!inputOk || !isIntegerIn(stepsValue, 1, 20) || !isIntegerIn(failValue, 0, 5)) return undefined;
  return { input: input as string, steps: stepsValue, failAttempts: failValue };
}

async function handleCreateJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { tooLarge, text } = await readBody(req);
  const errors: FieldError[] = [];

  const key = req.headers['idempotency-key'];
  if (key !== undefined && !ID_KEY_PATTERN.test(key)) {
    errors.push({ field: 'Idempotency-Key', message: 'Must be 1 to 128 characters of letters, digits, "_" or "-".' });
  }

  const mediaType = String(req.headers['content-type'] ?? '').split(';')[0]!.trim().toLowerCase();
  let valid: { input: string; steps: number; failAttempts: number } | undefined;
  if (mediaType !== 'application/json') {
    errors.push({ field: 'body', message: 'Content-Type must be application/json.' });
  } else {
    valid = validateCreateBody(text, tooLarge, errors);
  }
  if (errors.length > 0 || !valid) {
    sendInvalid(res, errors);
    return;
  }

  const payload = JSON.stringify({ input: valid.input, steps: valid.steps, failAttempts: valid.failAttempts });
  const outcome = withImmediate(db, (): { status: 200 | 201 | 409; row?: JobRow } => {
    if (key !== undefined) {
      const existing = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?').get(key) as unknown as JobRow | undefined;
      if (existing) {
        return existing.payload === payload ? { status: 200, row: existing } : { status: 409 };
      }
    }
    const id = randomUUID();
    const ts = nowIso();
    db.prepare(
      `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress_completed,
                         idempotency_key, payload, available_at, created_at, updated_at)
       VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, ?, ?, ?, ?)`,
    ).run(id, valid.input, valid.steps, valid.failAttempts, key ?? null, payload, Date.now(), ts, ts);
    const row = db.prepare('SELECT * FROM jobs WHERE id = ?').get(id) as unknown as JobRow;
    return { status: 201, row };
  });

  if (outcome.status === 409) {
    sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
    return;
  }
  sendJson(res, outcome.status, rowToJob(outcome.row!));
}

function handleListJobs(res: ServerResponse): void {
  const rows = db.prepare('SELECT * FROM jobs ORDER BY seq DESC').all() as unknown as JobRow[];
  sendJson(res, 200, { jobs: rows.map(rowToJob) });
}

function handleGetJob(res: ServerResponse, rawId: string): void {
  let id: string;
  try {
    id = decodeURIComponent(rawId);
  } catch {
    sendError(res, 404, 'not_found', 'No job with that id.');
    return;
  }
  const row = db.prepare('SELECT * FROM jobs WHERE id = ?').get(id) as unknown as JobRow | undefined;
  if (!row) {
    sendError(res, 404, 'not_found', 'No job with that id.');
    return;
  }
  sendJson(res, 200, rowToJob(row));
}

function handleHealth(res: ServerResponse): void {
  const row = db.prepare('SELECT last_seen FROM worker_heartbeat WHERE id = 1').get() as { last_seen: number } | undefined;
  const up = row !== undefined && Date.now() - Number(row.last_seen) <= HEARTBEAT_FRESH_MS;
  sendJson(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
}

function methodNotAllowed(res: ServerResponse): void {
  sendError(res, 405, 'method_not_allowed', 'Method not allowed for this path.');
}

async function route(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method ?? '';

  if (pathname === '/') {
    if (method !== 'GET') return methodNotAllowed(res);
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8', 'content-length': Buffer.byteLength(uiHtml) });
    res.end(uiHtml);
    return;
  }
  if (pathname === '/health') {
    if (method !== 'GET') return methodNotAllowed(res);
    return handleHealth(res);
  }
  if (pathname === '/api/jobs') {
    if (method === 'GET') return handleListJobs(res);
    if (method === 'POST') return handleCreateJob(req, res);
    return methodNotAllowed(res);
  }
  const match = JOB_ID_PATH.exec(pathname);
  if (match) {
    if (method !== 'GET') return methodNotAllowed(res);
    return handleGetJob(res, match[1]!);
  }
  sendError(res, 404, 'not_found', 'No such path.');
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer((req, res) => {
  route(req, res).catch((e: unknown) => {
    console.error('request failed:', e);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
    else res.end();
  });
});

server.listen(port, () => console.log(`server listening on ${port}`));

let shuttingDown = false;
function shutdown(): void {
  if (shuttingDown) return;
  shuttingDown = true;
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeAllConnections();
}
for (const signal of ['SIGTERM', 'SIGINT'] as const) {
  process.on(signal, shutdown);
}
